import {roles,esc} from './data.js';
import {readState,writeState} from './state.js';
export function controls(el,data){el.innerHTML=`<div class="graph-toolbar"><div class="segmented" aria-label="Режим графа"><button data-mode="2d">2D</button><button data-mode="3d">3D</button></div><label>Расположение<select data-state="layout"><option value="depth">По коленам</option><option value="cluster">По кластерам</option></select></label><label>Окраска<select data-state="color"><option value="neutral">Нейтральная</option><option value="role">Роли</option><option value="cluster">Кластеры</option></select></label><form id="graph-search" role="search"><label class="sr-only" for="graph-gid">Найти gid на графе</label><input id="graph-gid" placeholder="Полный gid" autocomplete="off"><button>Найти</button></form></div><div class="graph-filters"><label>Роль<select data-state="role"><option value="">Все роли</option>${Object.entries(roles).map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label><label>Кластер<select data-state="cluster"><option value="">Все кластеры</option>${data.clusters.map(c=>`<option value="${c.cluster_id}">${c.cluster_id} · ${c.n_nodes} уч.</option>`).join('')}</select></label><label>Глубина<select data-state="depth"><option value="">Все колена</option>${[0,1,2,3,4].map(d=>`<option>${d}</option>`).join('')}</select></label><label class="check-label"><input type="checkbox" data-state="seed">Только seed</label><button id="reset-filters" class="text-button">Сбросить фильтры</button><label>Окружение<select data-state="hops"><option value="">Полный граф</option><option value="1">1 переход</option><option value="2">2 перехода</option></select></label><label>Направление<select data-state="direction"><option value="all">Все связи</option><option value="in">Входящие</option><option value="out">Исходящие</option></select></label></div>`;
 for(const field of el.querySelectorAll('[data-state]'))field.onchange=()=>writeState({[field.dataset.state]:field.type==='checkbox'?(field.checked?'1':''):field.value});for(const button of el.querySelectorAll('[data-mode]'))button.onclick=()=>writeState({mode:button.dataset.mode});el.querySelector('#reset-filters').onclick=()=>writeState({role:'',cluster:'',depth:'',seed:'',hops:'',direction:'all'});
 const sync=()=>{const s=readState();for(const field of el.querySelectorAll('[data-state]'))if(field.type==='checkbox')field.checked=!!s[field.dataset.state];else field.value=s[field.dataset.state];for(const b of el.querySelectorAll('[data-mode]'))b.setAttribute('aria-pressed',String(b.dataset.mode===s.mode));el.querySelector('[data-state=hops]').disabled=!s.gid;el.querySelector('#graph-gid').value=s.gid;};sync();return sync;
}
